static void reveal(QWidget *w) {
 require(w,"Weather control absent");
 for(auto *p=w;p;p=p->parentWidget()) {
  for(auto *tabs:w->window()->findChildren<QTabWidget *>()) if(tabs->indexOf(p)>=0)tabs->setCurrentWidget(p);
  if(auto *scroll=qobject_cast<QScrollArea *>(p))scroll->ensureWidgetVisible(w);
 }
 events();require(w->isVisible()&&w->isEnabled(),"Weather control hidden/disabled");acceptanceView(*w);
}
static QJsonObject graph() {
 QJsonObject result;auto *m=Moderator::Instance();
 for(const auto &n:m->GetListOfObjects(Gmat::UNKNOWN_OBJECT))if(auto *o=m->GetConfiguredObject(n))result[QString::fromStdString(n)]=QString::fromStdString(o->GetGeneratingString(Gmat::SCRIPTING));
 return result;
}
static ODEModel *model() {auto *m=dynamic_cast<ODEModel *>(Moderator::Instance()->GetConfiguredObject("Forces"));require(m,"Weather force model absent");return m;}
static DragForce *drag(ODEModel *m) {require(m,"Weather ODE absent");for(int i=0;i<m->GetNumForces();++i)if(auto *d=dynamic_cast<DragForce *>(m->GetForce(i)))return d;throw std::runtime_error("Weather drag absent");}
